import{_ as a,o as s,c as t,ag as n}from"./chunks/framework.DoUXNnsN.js";const g=JSON.parse('{"title":"Git远程仓库","description":"","frontmatter":{"title":"Git远程仓库","aliases":["git clone","git remote","git push","git pull","git fetch","Gitee","GitHub","SSH Key","origin"],"tags":["工具与工程","Git"],"status":"ai-draft","sources":["https://git-scm.com/book/zh/v2/Git-基础-远程仓库的使用","https://help.gitee.com/repository/ssh-key/generate-and-add-ssh-public-key","https://docs.github.com/en/get-started/getting-started-with-git/about-remote-repositories","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":4},"headers":[],"relativePath":"50-工具与工程/Git/Git远程仓库.md","filePath":"50-工具与工程/Git/Git远程仓库.md"}'),i={name:"50-工具与工程/Git/Git远程仓库.md"};function o(p,e,d,l,c,r){return s(),t("div",null,[...e[0]||(e[0]=[n(`<blockquote><p>本篇是 <a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a> 入门路径的第 4 篇。读完你应该能：解释&quot;远程仓库&quot;是什么；用 <code>clone / push / pull / fetch</code> 和同事同步代码；读懂 push 被拒绝的原因并解决；生成 SSH Key 并选对 SSH 或 HTTPS；安全地保管凭据。</p><p>实验部分用一个<strong>本地裸仓库</strong>（<code>git init --bare</code>）充当&quot;远程服务器&quot;，两个文件夹 <code>alice</code>、<code>bob</code> 充当两位同事的电脑，所有输出都是在 Windows 11 + Git for Windows 2.54.0（Git Bash）里真实运行的。文中把冗长的临时路径缩写成 <code>.../server.git</code>。Gitee/GitHub 网页上的点击步骤依据官方文档整理，<strong>未在本机登录验证</strong>。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>远程仓库是放在另一台机器（公司服务器、Gitee、GitHub 等）上的 Git 仓库；<code>push</code> 把本地提交上传过去，<code>pull</code>/<code>fetch</code> 把别人的提交取下来，大家通过它交换代码。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a>。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/HTTP">HTTP</a>（了解 HTTPS 是加密的网页传输）、<a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a>（可选）。</li><li>如果要用 Gitee/GitHub：需要一个账号。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>只有本地仓库时，代码只在你电脑上：硬盘坏了就没了，同事也拿不到。远程仓库解决：</p><ol><li><strong>备份</strong>：多存一份在服务器上。</li><li><strong>协作</strong>：约定一个&quot;中心&quot;，大家都往里推、从里拉。</li><li><strong>代码评审与自动化</strong>：Gitee/GitHub 在远程之上提供 Pull Request、CI 等能力（见 <a href="/Encyclopedia/50-工具与工程/Git/Git工作流">Git工作流</a>、<a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a>）。</li></ol><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="git-是分布式的" tabindex="-1">Git 是分布式的 <a class="header-anchor" href="#git-是分布式的" aria-label="Permalink to &quot;Git 是分布式的&quot;">​</a></h3><p>每个人的电脑上都有<strong>完整的仓库和全部历史</strong>。&quot;远程仓库&quot;和你的本地仓库地位相同，只是被大家约定为&quot;交换点&quot;。所以服务器挂了也不致命：任何人的 clone 都能把它重建。</p><h3 id="术语" tabindex="-1">术语 <a class="header-anchor" href="#术语" aria-label="Permalink to &quot;术语&quot;">​</a></h3><ul><li><strong>origin</strong>：远程仓库的默认别名（昵称），指向 clone 时用的地址。可以有多个远程，各取别名。</li><li><strong>远程跟踪分支</strong>（remote-tracking branch）如 <code>origin/main</code>：你本地保存的&quot;上次联系时远程 main 的位置&quot;的快照，<strong>只在 fetch / pull / push 时更新</strong>，不是实时的。</li><li><strong>上游</strong>（upstream）：本地分支默认对应的远程分支。设置后 <code>git push</code>、<code>git pull</code> 不用再写参数。</li><li><strong>裸仓库</strong>（bare repository）：只有 <code>.git</code> 里的内容、没有工作区的仓库。服务器端的仓库都是裸的，因为没人在服务器上直接改文件。</li></ul><h3 id="命令速览" tabindex="-1">命令速览 <a class="header-anchor" href="#命令速览" aria-label="Permalink to &quot;命令速览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>git clone 地址 [文件夹]</code></td><td>把远程仓库完整复制到本地，自动设置 origin</td></tr><tr><td><code>git remote -v</code></td><td>看远程别名与地址</td></tr><tr><td><code>git remote add 别名 地址</code></td><td>给已有的本地仓库添加远程</td></tr><tr><td><code>git remote set-url 别名 新地址</code></td><td>改地址（如 HTTPS 改 SSH）</td></tr><tr><td><code>git push -u origin main</code></td><td>推送并设置上游（第一次用 <code>-u</code>）</td></tr><tr><td><code>git fetch</code></td><td>只下载远程新提交，更新 <code>origin/xxx</code>，<strong>不动</strong>你的工作区</td></tr><tr><td><code>git pull</code></td><td>= <code>fetch</code> + 合并（默认 merge）；<code>git pull --rebase</code> = <code>fetch</code> + rebase</td></tr></tbody></table><h2 id="逐步例子-本地-远程-演示" tabindex="-1">逐步例子（本地&quot;远程&quot;演示） <a class="header-anchor" href="#逐步例子-本地-远程-演示" aria-label="Permalink to &quot;逐步例子（本地&quot;远程&quot;演示）&quot;">​</a></h2><h3 id="第-1-步-建-服务器-并让-alice-克隆" tabindex="-1">第 1 步：建&quot;服务器&quot;并让 Alice 克隆 <a class="header-anchor" href="#第-1-步-建-服务器-并让-alice-克隆" aria-label="Permalink to &quot;第 1 步：建&quot;服务器&quot;并让 Alice 克隆&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git init --bare -b main server.git</span></span>
<span class="line"><span>Initialized empty Git repository in .../rm/server.git/</span></span>
<span class="line"><span>$ git clone server.git alice</span></span>
<span class="line"><span>Cloning into &#39;alice&#39;...</span></span>
<span class="line"><span>warning: You appear to have cloned an empty repository.</span></span>
<span class="line"><span>done.</span></span></code></pre></div><p><code>server.git</code> 就是&quot;远程&quot;（真实世界里它是 <code>https://gitee.com/...</code> 这样的地址）。克隆空仓库的警告是正常的。</p><h3 id="第-2-步-alice-提交并推送" tabindex="-1">第 2 步：Alice 提交并推送 <a class="header-anchor" href="#第-2-步-alice-提交并推送" aria-label="Permalink to &quot;第 2 步：Alice 提交并推送&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cd alice</span></span>
<span class="line"><span>$ echo &quot;# demo&quot; &gt; README.md</span></span>
<span class="line"><span>$ git add . &amp;&amp; git commit -m &quot;init readme&quot;</span></span>
<span class="line"><span>$ git remote -v</span></span>
<span class="line"><span>origin	.../server.git (fetch)</span></span>
<span class="line"><span>origin	.../server.git (push)</span></span>
<span class="line"><span>$ git push -u origin main</span></span>
<span class="line"><span>To .../server.git</span></span>
<span class="line"><span> * [new branch]      main -&gt; main</span></span>
<span class="line"><span>branch &#39;main&#39; set up to track &#39;origin/main&#39;.</span></span>
<span class="line"><span>$ git branch -vv</span></span>
<span class="line"><span>* main fe0423a [origin/main] init readme</span></span></code></pre></div><p><code>fetch</code> 和 <code>push</code> 各列一行，因为同一个别名可以用不同地址（少用）。<code>branch -vv</code> 里的 <code>[origin/main]</code> 表示本地 main 的上游是 origin/main。</p><h3 id="第-3-步-bob-克隆-两人都修改" tabindex="-1">第 3 步：Bob 克隆，两人都修改 <a class="header-anchor" href="#第-3-步-bob-克隆-两人都修改" aria-label="Permalink to &quot;第 3 步：Bob 克隆，两人都修改&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git clone server.git bob</span></span>
<span class="line"><span>Cloning into &#39;bob&#39;...</span></span>
<span class="line"><span>done.</span></span>
<span class="line"><span>$ cd bob &amp;&amp; git log --oneline</span></span>
<span class="line"><span>fe0423a init readme</span></span></code></pre></div><p>Bob 修改 README 并推送成功：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git push</span></span>
<span class="line"><span>To .../server.git</span></span>
<span class="line"><span>   fe0423a..5f4c386  main -&gt; main</span></span></code></pre></div><p>此时 Alice 还不知道。她在自己的仓库里新建 <code>alice.txt</code> 并提交，然后推送：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git push</span></span>
<span class="line"><span>To .../server.git</span></span>
<span class="line"><span> ! [rejected]        main -&gt; main (fetch first)</span></span>
<span class="line"><span>error: failed to push some refs to &#39;.../server.git&#39;</span></span>
<span class="line"><span>hint: Updates were rejected because the remote contains work that you do not</span></span>
<span class="line"><span>hint: have locally. This is usually caused by another repository pushing to</span></span>
<span class="line"><span>hint: the same ref. If you want to integrate the remote changes, use</span></span>
<span class="line"><span>hint: &#39;git pull&#39; before pushing again.</span></span></code></pre></div><p><strong>被拒绝了。</strong> 原因：远程 main 上有 Alice 本地没有的提交（Bob 的），Git 不允许 push 把别人的提交&quot;盖掉&quot;。这不是错误，是保护。解法：先把别人的取下来合并，再推。</p><h3 id="第-4-步-先-fetch-看看-再合并" tabindex="-1">第 4 步：先 fetch 看看，再合并 <a class="header-anchor" href="#第-4-步-先-fetch-看看-再合并" aria-label="Permalink to &quot;第 4 步：先 fetch 看看，再合并&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git fetch</span></span>
<span class="line"><span>From .../server</span></span>
<span class="line"><span>   fe0423a..5f4c386  main       -&gt; origin/main</span></span>
<span class="line"><span>$ git status</span></span>
<span class="line"><span>On branch main</span></span>
<span class="line"><span>Your branch and &#39;origin/main&#39; have diverged,</span></span>
<span class="line"><span>and have 1 and 1 different commits each, respectively.</span></span>
<span class="line"><span>  (use &quot;git pull&quot; if you want to integrate the remote branch with yours)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nothing to commit, working tree clean</span></span>
<span class="line"><span>$ git log --oneline --graph --all</span></span>
<span class="line"><span>* cae082c alice: add alice.txt</span></span>
<span class="line"><span>| * 5f4c386 bob: add line</span></span>
<span class="line"><span>|/</span></span>
<span class="line"><span>* fe0423a init readme</span></span></code></pre></div><p><code>diverged</code>（分叉）= 两边各有 1 个对方没有的提交，图和 <a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a> 里的三方合并场景一模一样。<code>fetch</code> 只是下载，没动工作区，所以先看后合是最稳的做法。这里用 <code>pull</code> 合并（本例 Bob 改的是 README，Alice 改的是新文件，不冲突）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git pull --no-rebase --no-edit</span></span>
<span class="line"><span>Merge made by the &#39;ort&#39; strategy.</span></span>
<span class="line"><span> README.md | 3 ++-</span></span>
<span class="line"><span> 1 file changed, 2 insertions(+), 1 deletion(-)</span></span>
<span class="line"><span>$ git push</span></span>
<span class="line"><span>To .../server.git</span></span>
<span class="line"><span>   5f4c386..c61756e  main -&gt; main</span></span>
<span class="line"><span>$ git log --oneline --graph --all</span></span>
<span class="line"><span>*   c61756e Merge branch &#39;main&#39; of .../server</span></span>
<span class="line"><span>|\\</span></span>
<span class="line"><span>| * 5f4c386 bob: add line</span></span>
<span class="line"><span>* | cae082c alice: add alice.txt</span></span>
<span class="line"><span>|/</span></span>
<span class="line"><span>* fe0423a init readme</span></span></code></pre></div><p><code>--no-rebase</code> 指明&quot;用 merge 方式整合&quot;，<code>--no-edit</code> 不弹编辑器，自动用默认合并信息。（新版 Git 在 pull 时会提示你必须选 merge 或 rebase；如果没配 <code>pull.rebase</code>，不指定会收到提示。）Bob 最后拉取，因为他本地没有新提交，所以是快进：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git pull</span></span>
<span class="line"><span>From .../server</span></span>
<span class="line"><span>   5f4c386..c61756e  main       -&gt; origin/main</span></span>
<span class="line"><span>Updating 5f4c386..c61756e</span></span>
<span class="line"><span>Fast-forward</span></span>
<span class="line"><span> alice.txt | 1 +</span></span>
<span class="line"><span> 1 file changed, 1 insertion(+)</span></span>
<span class="line"><span> create mode 100644 alice.txt</span></span></code></pre></div><h3 id="第-5-步-另一种做法-pull-rebase" tabindex="-1">第 5 步：另一种做法 pull --rebase <a class="header-anchor" href="#第-5-步-另一种做法-pull-rebase" aria-label="Permalink to &quot;第 5 步：另一种做法 pull --rebase&quot;">​</a></h3><p>另起一个相同场景：先别人推了 <code>a2</code>，我本地有未推的 <code>b1</code>，<code>push</code> 同样被拒绝。这次改用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git pull --rebase</span></span>
<span class="line"><span>Rebasing (1/1)Successfully rebased and updated refs/heads/main.</span></span>
<span class="line"><span>$ git log --oneline --graph</span></span>
<span class="line"><span>* 16c89ab b1</span></span>
<span class="line"><span>* 5a66b67 a2</span></span>
<span class="line"><span>* 7baf04a a1</span></span>
<span class="line"><span>$ git push</span></span>
<span class="line"><span>   5a66b67..16c89ab  main -&gt; main</span></span></code></pre></div><p>我的 <code>b1</code> 被&quot;搬&quot;到别人的 <code>a2</code> 之后，历史是一条直线，没有 &quot;Merge branch &#39;main&#39; of ...&quot; 这样的杂音提交。团队可以统一约定用哪种；只要你的 <code>b1</code> 还没推送，rebase 就是安全的（理由见 <a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a>）。</p><h3 id="第-6-步-看远程的整体状态" tabindex="-1">第 6 步：看远程的整体状态 <a class="header-anchor" href="#第-6-步-看远程的整体状态" aria-label="Permalink to &quot;第 6 步：看远程的整体状态&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git remote show origin</span></span>
<span class="line"><span>* remote origin</span></span>
<span class="line"><span>  Fetch URL: .../server.git</span></span>
<span class="line"><span>  Push  URL: .../server.git</span></span>
<span class="line"><span>  HEAD branch: main</span></span>
<span class="line"><span>  Remote branch:</span></span>
<span class="line"><span>    main tracked</span></span>
<span class="line"><span>  Local branch configured for &#39;git pull&#39;:</span></span>
<span class="line"><span>    main merges with remote main</span></span>
<span class="line"><span>  Local ref configured for &#39;git push&#39;:</span></span>
<span class="line"><span>    main pushes to main (up to date)</span></span></code></pre></div><h2 id="对接-gitee-github" tabindex="-1">对接 Gitee / GitHub <a class="header-anchor" href="#对接-gitee-github" aria-label="Permalink to &quot;对接 Gitee / GitHub&quot;">​</a></h2><h3 id="创建远程仓库" tabindex="-1">创建远程仓库 <a class="header-anchor" href="#创建远程仓库" aria-label="Permalink to &quot;创建远程仓库&quot;">​</a></h3><p>在网页上&quot;新建仓库&quot;，<strong>不要勾选</strong>&quot;用 README 初始化&quot;（如果你本地已有仓库）。创建后会给出两个地址：</p><ul><li>HTTPS：<code>https://gitee.com/你的用户名/仓库名.git</code>（GitHub 为 <code>https://github.com/...</code>）</li><li>SSH：<code>git@gitee.com:你的用户名/仓库名.git</code>（GitHub 为 <code>git@github.com:...</code>）</li></ul><p>把已有本地仓库接上去：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git remote add origin git@gitee.com:你的用户名/仓库名.git</span></span>
<span class="line"><span>git push -u origin main</span></span></code></pre></div><p>或者直接 <code>git clone 地址</code> 从零开始。把 HTTPS 换成 SSH 可以 <code>git remote set-url origin 新地址</code>（本机实测该命令可用，<code>remote -v</code> 立刻显示新地址；此处用了假地址，没有真正连接）。</p><h3 id="gitee-与-github-怎么选" tabindex="-1">Gitee 与 GitHub 怎么选 <a class="header-anchor" href="#gitee-与-github-怎么选" aria-label="Permalink to &quot;Gitee 与 GitHub 怎么选&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Gitee</th><th>GitHub</th></tr></thead><tbody><tr><td>访问速度（国内）</td><td>快</td><td>有时慢或不稳定</td></tr><tr><td>生态</td><td>国内团队常用，有企业版</td><td>全球开源社区中心，Actions 等生态最大</td></tr><tr><td>协作概念</td><td>Pull Request（PR）</td><td>Pull Request（PR）</td></tr></tbody></table><p>两者的 Git 命令完全一样，区别只在网页功能。本库自己用 Gitee 备份。</p><h3 id="https-还是-ssh" tabindex="-1">HTTPS 还是 SSH <a class="header-anchor" href="#https-还是-ssh" aria-label="Permalink to &quot;HTTPS 还是 SSH&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>HTTPS</th><th>SSH</th></tr></thead><tbody><tr><td>地址</td><td><code>https://...</code></td><td><code>git@gitee.com:...</code></td></tr><tr><td>认证</td><td>用户名 + 密码/<strong>令牌</strong>（Token）</td><td>密钥对（私钥在你电脑，公钥放在网站）</td></tr><tr><td>优点</td><td>穿透防火墙容易，无需配置密钥</td><td>配好后不用再输入，更安全</td></tr><tr><td>缺点</td><td>要处理令牌/凭据缓存</td><td>要一次性配置；22 端口有时被公司网络封</td></tr></tbody></table><p>GitHub 官方说明 HTTPS 已不再支持用账号密码做 Git 认证，需要用个人访问令牌（Personal Access Token）或凭据管理器。</p><h3 id="生成并添加-ssh-key" tabindex="-1">生成并添加 SSH Key <a class="header-anchor" href="#生成并添加-ssh-key" aria-label="Permalink to &quot;生成并添加 SSH Key&quot;">​</a></h3><p>SSH 密钥对 = 一把<strong>私钥</strong>（留在自己电脑，绝不外传）+ 一把<strong>公钥</strong>（交给网站）。比喻：公钥是你装在门上的锁，私钥是钥匙；锁可以复制给别人装，钥匙不行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh-keygen -t ed25519 -C &quot;you@example.com&quot;</span></span></code></pre></div><p>按提示选保存位置（默认 <code>~/.ssh/id_ed25519</code>）和密码短语（passphrase，建议设）。我在临时目录里（不动你的 <code>~/.ssh</code>）实际运行并用空密码短语演示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ssh-keygen -t ed25519 -C &quot;lab@example.com&quot; -f ../sshtest/id_ed25519 -N &quot;&quot;</span></span>
<span class="line"><span>Generating public/private ed25519 key pair.</span></span>
<span class="line"><span>Your identification has been saved in ../sshtest/id_ed25519</span></span>
<span class="line"><span>Your public key has been saved in ../sshtest/id_ed25519.pub</span></span>
<span class="line"><span>The key fingerprint is:</span></span>
<span class="line"><span>SHA256:uFg+yUy0n/vFrOgzD0+r5CpOf8yW6NMhzSERedU0Jdk lab@example.com</span></span>
<span class="line"><span>$ ls ../sshtest</span></span>
<span class="line"><span>id_ed25519  id_ed25519.pub</span></span></code></pre></div><p>两个文件：<code>id_ed25519</code> 是<strong>私钥</strong>，<code>id_ed25519.pub</code> 是<strong>公钥</strong>。<code>cat ~/.ssh/id_ed25519.pub</code> 得到一行以 <code>ssh-ed25519 AAAA...</code> 开头的文本，整行复制，粘贴到网站：Gitee 在&quot;个人设置 -&gt; 安全设置 -&gt; SSH 公钥&quot;，GitHub 在&quot;Settings -&gt; SSH and GPG keys&quot;（菜单名以官网为准）。然后测试：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh -T git@gitee.com</span></span></code></pre></div><p>Gitee 官方文档说明：成功时会提示认证成功（且不提供 shell 访问）。（⚠ 未在本机登录验证。）</p><h2 id="凭据与安全-不要把密码写进文件" tabindex="-1">凭据与安全：不要把密码写进文件 <a class="header-anchor" href="#凭据与安全-不要把密码写进文件" aria-label="Permalink to &quot;凭据与安全：不要把密码写进文件&quot;">​</a></h2><ul><li><strong>绝不要</strong>把用户名密码/令牌写进 <code>https://用户:密码@gitee.com/...</code> 这样的地址：它会以明文存进仓库的 <code>.git/config</code>，<code>remote -v</code> 也会显示它。</li><li><strong>绝不要</strong>把令牌、<code>.env</code>、<code>appsettings.Production.json</code>、私钥 <code>id_ed25519</code> 提交进仓库（在 <a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a> 里用 <code>.gitignore</code> 忽略）。一旦推到 Gitee/GitHub，就当它泄露了：立刻去网站吊销并重新生成。</li><li>HTTPS 用 Git for Windows 自带的 <strong>Git Credential Manager</strong>：第一次 push 会弹窗登录，之后存入 Windows 凭据管理器，不落在项目文件里。本机的 <code>credential.helper</code> 配置为 <code>manager</code>，说明它已启用：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git config --get-all credential.helper</span></span>
<span class="line"><span>manager</span></span></code></pre></div><ul><li>在本知识库的工作规则里，Gitee 凭据由使用者在终端自己输入，不进对话、不写进任何文件，也是同一个道理。</li><li>私钥可以设 passphrase，丢了电脑也没那么危险；公司电脑的私钥别拷到个人 U 盘。</li></ul><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>在一个空文件夹 <code>remote-lab</code> 里（Git Bash）：</p><ol><li><code>git init --bare -b main server.git</code></li><li><code>git clone server.git alice</code>（会警告克隆了空仓库，正常），进入后用 <code>git config user.name/user.email</code> 设置身份。</li><li>在 alice：创建 <code>a.txt</code>，<code>git add . &amp;&amp; git commit -m &quot;a&quot;</code>，<code>git push -u origin main</code>。</li><li>回到上一级，<code>git clone server.git bob</code>（这时远程已有内容，不再警告），进入后同样设置身份（用不同名字）。</li><li>在 bob：创建 <code>b.txt</code> 提交并 <code>git push</code>。</li><li>回到 alice：创建 <code>c.txt</code> 提交，直接 <code>git push</code>，应看到 <code>! [rejected] ... (fetch first)</code>。</li><li>用 <code>git pull --rebase</code>，再 <code>git push</code>，成功。<code>git log --oneline --graph</code> 应是一条直线。</li><li>在 bob：<code>git pull</code>，验证 <code>c.txt</code> 出现。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>解决</th></tr></thead><tbody><tr><td><code>rejected ... (fetch first)</code> / <code>non-fast-forward</code></td><td>远程有你没有的提交</td><td><code>git pull</code>（或 <code>--rebase</code>），解决冲突后再 push</td></tr><tr><td><code>fatal: Authentication failed</code></td><td>密码/令牌错误，或 GitHub 用了账号密码</td><td>用令牌或 SSH；清掉旧凭据（Windows 凭据管理器里删除对应条目）</td></tr><tr><td><code>Permission denied (publickey)</code></td><td>公钥没添加，或用错了密钥</td><td>确认公钥已添加到账户；<code>ssh -T</code> 测试；<code>ssh -v</code> 看详情</td></tr><tr><td><code>Could not resolve host</code> / 超时</td><td>网络、代理问题</td><td>检查网络；GitHub 访问不稳可换用 Gitee</td></tr><tr><td><code>fatal: refusing to merge unrelated histories</code></td><td>两个不相干的仓库（如远程已有 README，本地单独 init）</td><td>确认意图后 <code>git pull --allow-unrelated-histories</code></td></tr><tr><td>push 到了错误的远程/分支</td><td>没看 <code>remote -v</code> / <code>branch -vv</code></td><td>养成 push 前看一眼的习惯</td></tr><tr><td>想强制覆盖远程</td><td><code>git push --force</code> 会覆盖别人的提交</td><td>尽量不用；必须时用更安全的 <code>--force-with-lease</code>，且只用于你自己的分支</td></tr></tbody></table><p><code>--force-with-lease</code> 的含义：只有远程分支仍然是你上次看到的样子时才允许覆盖，否则拒绝，避免盖掉别人刚推的提交。</p><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> <code>git fetch</code> 和 <code>git pull</code> 的区别？ 答：<code>fetch</code> 只下载并更新 <code>origin/xxx</code>，不改你的分支和工作区；<code>pull</code> = <code>fetch</code> + 合并（或 rebase）。</p><p><strong>2.</strong> 为什么服务器端的仓库要用 <code>--bare</code>？ 答：服务器上没人编辑文件，不需要工作区；如果有工作区，往它的当前分支推送会导致工作区与仓库不一致，Git 默认会拒绝。</p><p><strong>3.</strong> push 被拒绝，Git 为什么不直接覆盖？ 答：覆盖会丢掉别人已推送的工作。拒绝是强制你先整合。</p><p><strong>4.</strong> 公钥和私钥哪个能发给别人？ 答：只有公钥。私钥泄露等于别人能冒充你。</p><p><strong>5.</strong> 误把令牌提交并推送到了 GitHub，仅仅再提交一次删掉它够吗？ 答：不够，历史里还有。要立刻吊销该令牌并重新生成，必要时再清理历史。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>远程仓库是大家约定的交换点；<code>origin</code> 是它的别名，<code>origin/main</code> 是你本地对它的记忆。</li><li>push 被拒绝 = 先整合（<code>pull</code> 或 <code>pull --rebase</code>）再 push；先 <code>fetch</code> 看清楚更稳。</li><li>认证：SSH 密钥或 HTTPS + 令牌；凭据永远不进仓库、不写进地址。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git工作流">Git工作流</a>、<a href="/Encyclopedia/10-计算机基础/计算机网络/HTTP">HTTP</a>、<a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Pro Git 远程仓库的使用：<a href="https://git-scm.com/book/zh/v2/Git-%E5%9F%BA%E7%A1%80-%E8%BF%9C%E7%A8%8B%E4%BB%93%E5%BA%93%E7%9A%84%E4%BD%BF%E7%94%A8" target="_blank" rel="noreferrer">https://git-scm.com/book/zh/v2/Git-基础-远程仓库的使用</a></li><li>Gitee 生成、添加 SSH 公钥：<a href="https://help.gitee.com/repository/ssh-key/generate-and-add-ssh-public-key" target="_blank" rel="noreferrer">https://help.gitee.com/repository/ssh-key/generate-and-add-ssh-public-key</a></li><li>GitHub 关于远程仓库（HTTPS 与 SSH）：<a href="https://docs.github.com/en/get-started/getting-started-with-git/about-remote-repositories" target="_blank" rel="noreferrer">https://docs.github.com/en/get-started/getting-started-with-git/about-remote-repositories</a></li></ul>`,84)])])}const u=a(i,[["render",o]]);export{g as __pageData,u as default};
